<template>

    <div id="recent-terms-container" class="container pt-3">
        <div id="rt-grid" class="row align-items-stretch">
            <div class="col-md-6 col-sm-12 col-lg-4 col-xl-4 h-100 mb-3 align-middle" v-for="term in terms">
                <div class="card ra-term dark:bg-slate-700 dark:text-slate-400" data-bs-toggle="popover" data-bs-placement="top"
                     :data-bs-title="term.term"
                     :data-bs-content="term.description"
                     :data-id="term.id">
                    <div class="card-body">
                        <span class="recentlyAddedTermDate float-end w-30">{{ moment().utc(term.created_at).fromNow() }}</span>
                        <span>{{ term.term }}</span> <span class="recentlyAddedTermRating float-end">{{ term.rating }}</span>
                    </div>
                </div>
            </div>
        </div>
    </div>

</template>

<script>
import * as bootstrap from 'bootstrap';

export default {
    name: "RecentlyAddedTermsComponent",
    data () {
        return {
            terms: null
        }
    },
    methods: {
        moment: function () {
            return moment;
        },
        pollData () {
            this.polling = setInterval(() => {
                this.getTerms();
            }, 60000)
        },
        getTerms: function() {
            var context = this;

            $.ajax({
                async: true,
                method: "GET",
                headers: {
                    'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
                },
                url: "/term/get-recently-added-terms"
            })
            .done(function( data ) {
                if(data.status) {
                    context.terms = data.terms;
                }
            });
        }
    },
    beforeDestroy () {
        clearInterval(this.polling)
    },
    created () {
        this.pollData()
    },
    mounted() {
        this.getTerms();

        let termRatingObjs = document.getElementsByClassName('recentlyAddedTermRating')

        for(let index = 0;index < termRatingObjs.length;index++)
        {
            let element = termRatingObjs[index];
            utils.setColorByNumber(element.innerHTML, element);
        }

        let existingPopover = document.querySelector('.popover');

        if(existingPopover)
        {
            existingPopover.remove();
        }

        const popoverTriggerList = $('[data-bs-toggle="popover"]');

        for(var i = 0; i < popoverTriggerList.length; i++) {
            var el = popoverTriggerList[i];

            var tt = new bootstrap.Popover(el, {
                html: true,
                trigger: 'hover focus',
                delay: 1000
            });
        }
    }
}
</script>

